package vn.edu.eaut.lab5.bus;
import vn.edu.eaut.lab5.dal.HoaDonDAL; import vn.edu.eaut.lab5.model.*; import java.math.BigDecimal; import java.sql.SQLException; import java.time.LocalDate; import java.util.List;
public class HoaDonBUS {private final HoaDonDAL dal=new HoaDonDAL();public int save(HoaDon h)throws SQLException{if(h.getMaKh()<=0)throw new IllegalArgumentException("Phải chọn khách hàng");if(h.getChiTiet()==null||h.getChiTiet().isEmpty())throw new IllegalArgumentException("Hóa đơn phải có ít nhất một dòng");BigDecimal total=BigDecimal.ZERO;for(ChiTietHoaDon x:h.getChiTiet()){if(x.getSoLuong()<=0)throw new IllegalArgumentException("Số lượng phải lớn hơn 0");x.setThanhTien(x.getDonGia().multiply(BigDecimal.valueOf(x.getSoLuong())));total=total.add(x.getThanhTien());}h.setTongTien(total);if(h.getNgayLap()==null)h.setNgayLap(LocalDate.now());return dal.saveTransaction(h);}public List<HoaDon> search(LocalDate a,LocalDate b,String k,BigDecimal f,BigDecimal t,int limit,int offset)throws SQLException{return dal.search(a,b,k,f,t,limit,offset);}public int count(LocalDate a,LocalDate b,String k,BigDecimal f,BigDecimal t)throws SQLException{return dal.count(a,b,k,f,t);}}
